// Append new releases at the top; published entries are historical records.
const RELEASE_180={version:'180',date:'2026-10-06',title:'Actions lisibles, Recherche cumulative et Modules d’opération',changes:[
 'Dossiers et menaces : Effets de l’action devient un bouton à droite. Les détails affichent uniquement les effets mécaniques ; la stat, le talent et les effets associés (Hack, Recherche, Module) sont regroupés à gauche sur la même ligne.',
 'Énergie et exposition figurent ensemble sous les agents, avec les valeurs réelles après réduction des talents et des mentions explicites de réussite ou d’échec.',
 'Boost avec une icône de fusée au-dessus des pourcentages : +10% -6cr, activable et désactivable avant confirmation. Les crédits ne sont débités que lors de la confirmation de l’ordre renforcé ; plafond à 90 % et raisons d’indisponibilité conservés.',
 'Recherche : nom et icône de dossier avec loupe uniformisés. Tous les gains s’additionnent, même pendant un seul tour : contact, intrusion et première résolution de l’IA +1, contre-espionnage +2. Trois points découvrent un dossier, surplus conservé. Progression existante conservée à la reprise.',
 'Appuis technologiques renommés Modules d’opération, avec une icône commune. Drone et protection indiquent Module · 1 place dans leurs fiches. L’onglet reste Opération ; les deux places partagées et les commandes d’annulation restent accessibles.',
 'Opération : retrait des trois textes explicatifs signalés, de la boîte Ordres de l’unité et du nombre d’opérations en cours. Les places et cartes de Module remontent dans la page.',
 'Manuel, prévisions et rapports actualisés. Toutes les corrections précédentes restent incluses ; les fichiers de jeu publiés sont identiques à ceux synchronisés sur GitHub.'
]};
const RELEASE_179={version:'179',date:'2026-10-06',title:'Quatre pays et repêchage en mode Avancé',changes:[
 'Nouvelles parties : quatre superpuissances actives parmi six pays au choix. Solo : votre pays et trois PNJ aléatoires. Multijoueur : deux humains et deux PNJ, trois humains et un PNJ, ou quatre humains ; les PNJ utilisent les pays non choisis.',
 'Menu Mode de jeu près de la difficulté, en solo et dans le salon : Régulier par défaut pour la sélection libre, ou Avancé pour des agents exclusifs à un seul pays.',
 'Avancé : confirmation des pays humains, tirage des PNJ et de l’ordre aléatoire, puis repêchage des seize agents en quatre rondes, 1 à 4 / 4 à 1 / 1 à 4 / 4 à 1. Les PNJ choisissent automatiquement ; l’hôte ouvre le repêchage multijoueur après les confirmations.',
 'Après le repêchage : réorganisation des quatre agents, choix du Chef au premier poste et confirmation de chaque équipe. En multijoueur, seul l’hôte peut lancer lorsque toutes les équipes sont confirmées et les joueurs connectés. Le salon et le repêchage sont conservés à la reprise.',
 'Relève en Avancé : propositions parmi les anciens agents, hors des seize du repêchage. Réservation exclusive des recrues humaines et PNJ pendant les deux tours de recrutement. Bouton Renforts & relève retiré du menu Agents ; recrutement conservé pour les postes vacants et les annonces de décès.',
 'Passage clandestin réussi : exposition remise à zéro, avec ou sans arme. Prévisions, rapports et manuel actualisés ; pénalité d’échec et risques conservés.',
 'Anciennes campagnes : leurs participants et équipes sont conservés. Toutes les corrections des builds 177 et 178 restent incluses. GitHub et le jeu publié utilisent les mêmes fichiers.'
]};
const RELEASE_178={version:'178',date:'2026-10-06',title:'Actions réactives et version synchronisée',changes:[
 'Carte : un double-clic ouvre directement le menu de l’agent, même lorsque son pays n’est pas centré. Le centrage du simple clic attend brièvement pour conserver le portrait sous le pointeur.',
 'Attaque reportée : nouvelle annonce avec Image à venir, motif, pays ciblé et ancienne puis nouvelle échéance. Les changements de pays sont signalés ; la protection reste à son emplacement.',
 'Annulation d’un ordre avant son premier tour de mission : le renfort payé en crédits est remboursé, une seule fois. Le renfort d’une mission commencée reste consommé.',
 'Recueillir une preuve et Intrusion numérique : interruption immédiate dès que la cible quitte le pays. L’agent est disponible dès le tour suivant, sans fatigue supplémentaire ni jet de réussite.',
 'Démarche diplomatique : coûts de confiance 15 / 15 / 10 / 5 selon le niveau de coopération. Soutien médical : +12 énergie. Interface, manuel, moteur solo et multijoueur alignés.',
 'GitHub et jeu publié utilisent les mêmes fichiers de jeu. Toutes les corrections de la version 177, dont les statistiques 9-4-7 d’Iris, sont conservées.'
]};
const RELEASE_177={version:'177',date:'2026-10-05',title:'Enquêtes accessibles et bilan complet',changes:[
 'Multijoueur : Confirmer mes 4 agents devient le premier contrôle du salon, avec un bouton plus visible et le nombre d’agents sélectionnés.',
 'Fenêtres d’enquête : numéros des étapes retirés, indicateurs ouvert, fermé et terminé conservés avec leurs couleurs.',
 'Carte : les cibles connues et menaces du pays restent accessibles lorsqu’un agent est sélectionné.',
 'Bilan des opérations : toutes les actions actuelles sont affichées, y compris celles jamais effectuées à 0 / 0. Les anciens résultats restent conservés.',
 'Iris : Analyse 9, Habileté 4, Sang-froid 7. Mise à jour des nouvelles équipes et des sauvegardes solo et multijoueur ; les missions déjà engagées conservent leurs chances.'
]};
const RELEASE_176={"version":"176","date":"2026-10-05","title":"BB1 compare ses appuis et prépare ses interventions","changes":["BB1 compare financement, soutien médical et démarche diplomatique avant de demander une faveur. Il tient compte des chances réellement améliorées, du délai commun de deux tours, des crédits nécessaires et des revenus liés à la confiance.","Les trois modules sont choisis pour leurs effets utiles : lot de vérifications, prolongation d’une position ou accélération d’un voyage. Les activations anticipées préservent un créneau terrain et les crédits d’intervention.","Un agent à l’étranger peut rechercher une arme lorsqu’elle améliore une arrestation à venir, pendant une attente de vérification. BB1 compare aussi un déplacement pour extraire un coéquipier détenu.","Correction des décisions de BB1 uniquement. Les propositions de passage clandestin sans exposition, de soutien médical à +12 et de diplomatie moins coûteuse sont évaluées séparément par simulations ; les règles du jeu publié restent celles de la version 175."]};
const RELEASE_175={"version":"175","date":"2026-10-05","title":"BB1 utilise le passage clandestin","changes":["BB1 compare désormais le passage clandestin au voyage sous passeport pour ses enquêtes : arme conservée, exposition à l’arrivée, chances de réussite, fatigue, durée et coût des renforts. Le passage est choisi lorsque ses avantages compensent ses risques.","La logistique prioritaire reste propre aux voyages sous passeport. BB1 en tient compte dans cette comparaison et préserve les crédits réservés à ses protections.","Les agents en passage clandestin sont pris en compte à leur destination pour répartir les effectifs et éviter les déplacements redondants.","Correction des choix de BB1 uniquement : probabilités, coûts et effets des actions conservés. Facile, Normal et Expert gardent leur comportement."]};
const RELEASE_174={"version":"174","date":"2026-10-05","title":"BotBrillant1 : une nouvelle IA au choix","changes":["BotBrillant1 (BB1) devient un quatrième choix dans les paramètres de nouvelle partie et dans le salon multijoueur. L’hôte choisit le niveau des pays contrôlés par l’ordinateur.","BB1 planifie ses enquêtes et protections sur plusieurs tours, répartit les rôles des agents et réserve les ressources utiles à ses objectifs. Il utilise les mêmes actions, probabilités et ressources que les joueurs.","Facile, Normal et Expert conservent leur comportement ; Normal reste le choix par défaut. Les campagnes existantes gardent leur niveau IA.","La mémoire des objectifs de BB1 est conservée dans les sauvegardes et reste privée en multijoueur. Aucun changement des règles, des menaces ou des récompenses."]};
const RELEASE_173={version:'173',date:'2026-10-04',title:'Douze criminels, six cibles par campagne',changes:['Sable, Rook, Nyx, Silas, Vega et Onyx rejoignent Fracture avec leurs portraits, rôles, profils et trois pièces de preuve chacun.', 'Chaque nouvelle campagne tire six criminels distincts parmi les douze et les répartit en trois cellules de deux. L’Architecte reste toujours présent. Les liens et conclusions des enquêtes suivent les partenaires réellement tirés.', 'Règles, placements, menaces et équilibrage conservés : trois dossiers portent chacun une falsification parmi leurs deux premières preuves ; la troisième reste authentique. Aucun nouveau tirage à la reprise d’une sauvegarde.', 'Identités, portraits et preuves synchronisés en multijoueur. Les campagnes existantes conservent leur distribution initiale.']};
const RELEASE_172={version:'172',date:'2026-10-04',title:'Libellés du menu simplifiés',changes:['Menu principal : Multijoueur sans mention bêta ; Patch notes sans préfixe Nouveautés. Compteur des notes non lues conservé.', 'Validation du rythme en Normal par simulations séparées ; aucune modification des règles ni de la difficulté dans cette version.']};
const RELEASE_171={version:'171',date:'2026-10-04',title:'Menaces mieux réparties',changes:['Nouvelles campagnes : les 17 menaces, Architecte compris, sont réparties à raison de deux ou trois par pays secondaire. Au moins six tours séparent deux attaques initialement prévues dans un même pays.', 'Fracture privilégie les pays moins ciblés lors des transferts et évite les attaques trop rapprochées. Les reports préservent au moins quatre tours entre les attaques dans un même pays ; un report bloqué ne consomme aucune ressource.', 'Calendrier, nombre d’attaques et délais d’annonce conservés. Les campagnes existantes conservent leurs pays et échéances ; les prochains ajustements de Fracture suivent les nouvelles limites.']};
const RELEASE_170={version:'170',date:'2026-10-04',title:'Rétablissement des fenêtres',changes:['Correction d’une variable de débriefing supprimée lors de la refonte des dossiers, qui bloquait la fonction commune d’ouverture des fenêtres.', 'Ouverture des agents et des dossiers rétablie, ainsi que le passage du portrait d’un agent dans un dossier à sa fenêtre d’action. Tests de régression sur les fonctions réelles de l’application.']};
const RELEASE_169={version:'169',date:'2026-10-04',title:'Un parcours d’enquête en cinq étapes',changes:[
 'Onglet Enquête et fenêtres de dossier : accès local, deux preuves, une validation, préparation et localisation en parallèle, puis arrestation. Identification automatique conservée pour les portraits, sans étape ni condition supplémentaire.',
 'Actions présentées par boutons. Étapes sélectionnées en bleu, indisponibles en rouge pâle et accomplies avec un crochet vert. Obtenir un mandat remplace Négocier une autorisation : action facultative, une fois par pays.',
 'La deuxième preuve reste vérifiable après la première. Plusieurs agents peuvent chercher des preuves ou recevoir la même mission, notamment préparer une arrestation ou procéder à l’arrestation. La fenêtre reste ouverte entre les affectations et affiche les missions engagées.',
 'Préparation et arrestation simultanées : après un succès, les tentatives devenues inutiles sont interrompues selon les règles existantes. Boost unique de 10 points et filtrage des agents locaux conservés ; vérification au QG.'
]};
const RELEASE_168={version:'168',date:'2026-10-04',title:'Catégories des dossiers et compteur des menaces',changes:[
 'Dossiers : trois boutons Contact, Preuves et Arrestation filtrent le menu déroulant. Les actions suivent l’ordre demandé dans chaque catégorie ; intimidation et drone figurent dans plusieurs catégories lorsque pertinent.',
 'Les conditions manquantes cliquables ouvrent automatiquement la catégorie de l’action nécessaire. Disponibilités, étapes accomplies et choix des agents sont conservés.',
 'Le compteur Menaces affiche uniquement les attaques annoncées non couvertes par votre pays à leur échéance. Une protection étrangère, en préparation ou expirant avant l’attaque ne réduit pas ce compteur. Toutes les menaces restent consultables.'
]};
const RELEASE_167={version:'167',date:'2026-10-04',title:'Dossiers compacts et protection depuis les menaces',changes:[
 'Fenêtres de dossier : actions condensées dans un menu déroulant conservant leur ordre, avec état terminé ou indisponible. Les explications détaillées sont repliables.',
 'Choix des agents limité au pays de l’action, ou au QG pour vérifier une preuve ; agents en déplacement déjà commencé exclus. Un clic sur leur portrait ferme le dossier et ouvre leur fenêtre habituelle.',
 'Panneau du pays : boutons des menaces annoncées avec cellule et tour de l’attaque. Une fenêtre dédiée propose uniquement Protéger une infrastructure, les agents locaux et la confirmation directe.',
 'Protection : état de couverture à l’échéance et avertissement si la préparation se termine trop tard ou si la protection expirerait avant l’attaque.',
 'Correction du débordement des portraits de cibles non identifiées. Règles du moteur, boost unique et restrictions multijoueurs conservés.'
]};
const RELEASE_166={version:'166',date:'2026-10-04',title:'Enquêtes accessibles depuis le pays',changes:[
 'Globe : les cibles connues apparaissent en haut du panneau du pays, avec leur portrait lorsque leur identité est confirmée. Les indicateurs Accès, Mandat, Planque, Hack et Protection sont regroupés près du nom du pays.',
 'Un clic sur une cible ouvre une fenêtre compacte : actions dans le même ordre que le menu habituel, portraits des agents, disponibilités, chances réelles et durée. Confirmation de l’ordre dans cette fenêtre, qui reste ouverte.',
 'Actions bloquées consultables, conditions manquantes cliquables et étapes accomplies signalées. La vérification sélectionne uniquement une pièce du dossier et un agent au QG ; les agents ailleurs ou occupés affichent leur motif d’indisponibilité.',
 'Renfort unique de +10 points, soumis au coût et au plafond habituels. Affectations par le moteur existant en solo et par l’hôte en multijoueur ; observateurs et joueurs ayant confirmé leur tour en consultation seule.'
]};
const RELEASE_165={version:'165',date:'2026-10-04',title:'IA Facile et Normal : enquêtes et diplomatie',changes:[
 'Facile et Normal : préférence réduite pour l’intrusion numérique afin de mieux valoriser la collecte de preuves selon les compétences des agents.',
 'Facile et Normal : les démarches gouvernementales peuvent améliorer une relation diplomatique lorsqu’un dossier avancé et une action disponible en bénéficient. Une réserve de confiance est conservée.',
 'Expert conserve son comportement précédent. Prix, revenus, agents, talents, risques de voyage et délais de réaction aux menaces inchangés.',
 'Validation : 1 000 nouvelles parties entièrement IA par difficulté. Victoire collective / crise / tour 30 : Facile 21,0 / 23,3 / 55,7 % ; Normal 32,6 / 16,3 / 51,1 % ; Expert 51,9 / 10,3 / 37,8 %. Ces simulations ne représentent pas directement les parties avec des joueurs humains.'
]};
const RELEASE_164={version:'164',date:'2026-10-03',title:'Menaces : davantage de temps pour réagir',changes:[
 'Les menaces sont révélées cinq tours à l’avance : une attaque prévue au tour 10 est visible dès le tour 5. Même préavis pour le joueur, les PNJ et les invités multijoueurs.',
 'Un changement de pays est interdit lorsqu’il reste moins de quatre tours avant l’attaque. La transition entre les tours conserve au moins trois tours pour réagir.',
 'Fracture peut encore déplacer une attaque pendant sa phase anticipée, en réaction à une protection déjà établie. Les reports de date restent possibles ; la protection reste dans son pays initial.',
 'Wiki, alertes et rapports de cellules démantelées alignés sur le nouveau préavis. Les politiques des trois niveaux IA restent celles validées ; les statistiques d’équilibrage précédentes correspondent aux anciennes règles de menace.'
]};
const RELEASE_163={version:'163',date:'2026-10-03',title:'Équilibrage des trois niveaux IA',changes:[
 'Facile : davantage de continuité dans les enquêtes, protections urgentes et arrestations renforcées, relais pour les dossiers préparés.',
 'Normal : meilleure progression vers les objectifs collectifs, collecte en parallèle de la vérification et utilisation plus adaptée des modules et des crédits.',
 'Expert : gestion plus active de l’énergie et de l’exposition, protection en urgence et renfort par un meilleur intervenant sur les dossiers déjà préparés. Les aides gouvernementales conservent leurs coûts et limites.',
 'Les niveaux modifient les décisions des PNJ, sans bonus caché aux jets ni modification des règles de crise ou de prestige. Intégration en solo et en multijoueur.',
 'Validation sur 1 000 parties entièrement IA par niveau : victoire collective / crise / tour 30 — Facile 17,7 / 38,9 / 43,4 % ; Normal 35,4 / 34,5 / 30,1 % ; Expert 64 / 17,8 / 18,2 %. Lots de départ différents ; ces résultats ne mesurent pas la concurrence humaine au prestige.'
]};
const RELEASE_162={version:'162',date:'2026-10-03',title:'IA Normal : poursuivre les enquêtes',changes:[
 'Les pays IA en Normal donnent davantage de priorité à leur dossier local le plus avancé pour poursuivre la collecte, la préparation et l’arrestation. Une menace susceptible de faire atteindre le seuil de crise reste prioritaire.',
 'Lorsqu’un dossier est prêt mais sa position expirée, le relais satellite peut accélérer la nouvelle localisation. Une position encore valable permet l’arrestation sans achat inutile de relais.',
 'Aucun bonus caché : chances, coûts, fatigue, règles de crise et prestige conservés. Les comportements Facile et Expert restent inchangés.',
 'Tests appariés sur de nouveaux départs : en Normal hybride, 3,61 arrestations par partie contre 2,87 et première arrestation vers T13,5 contre T15,6. Résultats de simulations entièrement IA, pas de parties humaines.'
]};
export const PATCH_NOTES=[RELEASE_180,RELEASE_179,RELEASE_178,RELEASE_177,RELEASE_176,RELEASE_175,RELEASE_174,RELEASE_173,RELEASE_172,RELEASE_171,RELEASE_170,RELEASE_169,RELEASE_168,RELEASE_167,RELEASE_166,RELEASE_165,RELEASE_164,RELEASE_163,RELEASE_162,{"version": "161", "date": "2026-10-03", "title": "Raven : une posture plus naturelle", "changes": ["Nouvelle pose de Raven intégrée aux visuels plein pied, portraits et fiche illustrée. Cadrage harmonisé avec les autres agents, en solo et en multijoueur."]},{"version": "160", "date": "2026-10-03", "title": "Dossiers des agents, talents et décisions des PNJ", "changes": ["Cartes de sélection : en-tête gris uni jusqu’au nom, dégradé limité au surnom et aux drapeaux. Bouton ? indépendant sur les deux faces ; dossier avec plein pied, statistiques, talents et biographie, en solo et multijoueur.", "Infiltration réduit de 20 % tous les gains d’exposition des missions, réussite ou échec. Endurance réduit de 25 % toutes leurs dépenses d’énergie. Arrondi supérieur ; récupération inchangée.", "Planification tactique conserve ses bonus et réserve +5 à la prochaine arrestation de l’équipe sur la cible après une préparation réussie. Bonus consommé au jet ; annulation ou interruption préalable le préserve. Langues étrangères se cumule avec les autres talents pour les planques et armes.", "PNJ : coûts réels, risques, tacticien, chef, soins sur place, urgences et soutien utile intégrés aux choix. Différences Facile/Normal/Expert conservées, sans bonus caché.", "Sauvegardes : mise à jour de l’énergie restante des anciennes missions, sans modifier les dépenses passées ni les chances déjà confirmées. Tests de régression et simulations sur les trois difficultés."]},{version:'159',date:'2026-10-03',title:'Chef et coordination',changes:['Nouvelles parties : le premier agent choisi devient Chef. Coordination accorde +5 points aux autres agents de son équipe dans le même pays, au QG comme à l’étranger, dans la limite habituelle de 90 %.','Le chef doit être vivant, libre et hors transit. Bonus indiqué dans la préparation et fixé à la confirmation de l’ordre ; statut conservé en solo, en multijoueur et dans les sauvegardes. Les équipes IA disposent aussi d’un chef.','Les parties existantes restent sans chef si aucun n’avait été choisi. Les trois talents d’origine sont conservés ; Chef apparaît comme un statut supplémentaire.','Intimidation : plusieurs agents peuvent préparer une tentative sur la même cible. Une intimidation déjà réussie reste non répétable ; les autres tentatives devenues inutiles sont interrompues.']},{version:'158',date:'2026-10-03',title:'Cartes et sélection affinées',changes:['Nom, surnom et informations remontés ; dégradé sombre terminé sous le surnom, y compris sur plusieurs lignes.','Espace accru avant les valeurs des statistiques, toujours alignées. Encadrés des talents ajustés à leur texte.','Talents affichés par ordre alphabétique, sur les deux faces des cartes et dans les fiches des agents.','Petit bouton X en bas à gauche des portraits sélectionnés pour libérer leur emplacement, en solo et en multijoueur.']},{version:'157',date:'2026-10-03',title:'Cartes recto verso et composition de l’unité',changes:['Cartes des agents : dégradé presque noir, bouton de rotation indépendant de la sélection et animation recto verso. Portrait au dos avec nom, nationalités, statistiques et icônes des talents.','Commandes pour afficher tous les portraits ou tous les plein pied, avec conservation des vues pendant les tris et filtres.','Quatre emplacements de portraits au-dessus des filtres : remplissage de la première place libre et couronne sur le futur chef. Aucun bonus de chef activé.','Six pays sur une même rangée, textes introductifs retirés et disposition adaptée aux résolutions, en solo et en multijoueur.']},{version:'156',date:'2026-10-03',title:'Alba et Raven rejoignent SIGMA',agents:['p25','p26'],changes:['Alba — La Faussaire, France et Brésil : A7, H7, SF6 ; Diplomatie, Endurance et Infiltration.','Raven — L’Expérimentée, Chine : A5, H6, SF9 ; Secourisme, Langues étrangères et Combat.','Ordre par défaut : Rocket, Alba, puis Raven. Profils et visuels disponibles en solo, en multijoueur et dans les dossiers.','Portraits ajoutés aux annonces de nouvelles recrues dans les patch notes.','Cases de stats compactes, chiffres alignés près des libellés et dégradé gris foncé en haut des cartes de sélection.']},{version:'155',date:'2026-10-03',title:'Quatre agents par rangée sur ordinateur',changes:['Sélection solo et multijoueur : quatre agents par rangée dès 900 px de largeur, avec portraits plein pied réduits, textes et espacements compacts.','Sur les écrans de 900 à 1250 px, les paramètres passent sous la sélection pour préserver la largeur des cartes.']},{version:'154',date:'2026-10-03',title:'Fiches agents : cadrage et lisibilité',changes:['Drapeaux à droite des surnoms, statistiques et talents remontés, portraits centrés avec un cadrage homogène. Image de Mira nettoyée sans changer sa posture.','Cartes adaptées à la largeur disponible : quatre colonnes sur grand écran, deux sur écran intermédiaire et une sur mobile.','Une seule infobulle au style du jeu pour les statistiques et talents, avec les informations essentielles et sans rappels généraux.']},{version:'153',date:'2026-10-03',title:'Sélection d’équipe : portraits plein pied, tri et filtres',changes:['Présentation solo et multijoueur : agents plein pied à gauche, identité et statistiques à droite, talents plus petits sous les statistiques et alignés à droite. Icônes du jeu conservées.','Tri décroissant par Analyse, Habileté ou Sang-froid ; Défaut conserve l’ordre du roster. Filtre par talent combinable au tri, sans modifier les agents déjà sélectionnés.','Infobulles des statistiques : actions réellement influencées et effet sur les chances. Descriptions des douze talents revues selon les règles du moteur, bonus non cumulables et soins de terrain inclus.']},{version:'152',date:'2026-10-03',title:'Secourisme de terrain et nouvelles fiches',changes:['Secourisme remplace ses anciens bonus : en fin de tour, chaque secouriste soigne une blessure dans son pays, sur un coéquipier en priorité, sinon sur lui-même, sans rendre d’énergie. Disponible après une autre action ; agents en voyage, capturés ou hors service exclus.','Fiches de sélection solo et multijoueur : portrait et identité côte à côte, statistiques en trois cases colorées, icônes réduites et talents fixés sur deux rangées. Quatre agents par rangée sur grand écran.','Descriptions des talents, des soins, des risques et wiki actualisés.']},{version:'151',agents:['p23','p24'],date:'2026-10-03',title:'Selin et Rocket rejoignent SIGMA',changes:['Deux agents ajoutés après Dante, dans l’ordre Selin puis Rocket, disponibles en solo et en multijoueur.','Selin — La Stratège, Turquie : Analyse 6, Habileté 8, Sang-froid 6 ; Langues étrangères, Informatique et Planification tactique.','Rocket — Le Médiateur, Canada : Analyse 8, Habileté 8, Sang-froid 4 ; Secourisme, Diplomatie et Enquête.','Portraits, fiches, silhouettes et messages de mission intégrés dans le style des autres agents.']},{version:'150',date:'2026-10-03',title:'Arrestations simultanées et menu Mods',changes:['Arrestations visant la même cible : priorité aux chances finales de réussite, puis au sang-froid ; tirage au sort en cas d’égalité complète. Une tentative échouée laisse la suivante intervenir.','Après une arrestation réussie, les autres tentatives deviennent sans objet, sans échec ; leur boost inutilisé est remboursé, le temps et l’énergie mobilisés restent consommés.','Menu principal remonté, nouvelle accroche et résumé de campagne dans le bouton Continuer.','Nouveau bouton Mods : activation du Bureau des enquêtes déplacée hors des paramètres.']},{version:'149',date:'2026-10-03',title:'Reprise multijoueur et Bureau des enquêtes',changes:['Reprise de la session multijoueur après actualisation : l’hôte retrouve sa sauvegarde hébergée, y compris depuis son propre lien ; les invités retrouvent leur connexion. Accès à la reprise depuis les deux écrans multijoueurs.','Nouvelles campagnes : trois menaces propres à l’Architecte aux tours 16, 22 et 28, annulées par son arrestation. Une attaque réussie augmente désormais la crise de 30 points au lieu de 15.','Attaques annulées : exclusion explicite de la résolution et des résultats par identifiant, même lorsque plusieurs attaques visent le même pays.','Bilan : survol du graphique énergie/exposition avec action et résultat ; une étoile pour une réussite à 50 % ou moins, deux à 25 % ou moins.','Bureau intégré comme les autres panneaux, menu de gauche accessible, fermeture vers Monde. Fiches de mission larges, ancrées en haut du panneau ; localisation disponible en vert.','Bureau : relations diplomatiques, cases de sélection pour affectations et déplacements multiples, récupération d’une arme, énergie/exposition dans les fiches et la barre des agents. Cibles arrêtées masquées.','Affectations parallèles permises selon les règles du moteur ; double intimidation sur une même cible bloquée pour une équipe. Pays responsable de l’arrestation affiché dans les enquêtes.','Menaces : compteur maintenu après consultation, sans couleur d’alerte.']},{version:'148',date:'2026-10-02',title:'Menu latéral dégagé',changes:['Le menu de gauche reste sous l’en-tête et le fil d’informations, même lorsqu’un bandeau multijoueur est présent.','Le positionnement se réajuste lorsque la hauteur du bandeau multijoueur change.']},{version:'147',date:'2026-10-02',title:'Nationalités et passeports séparés',changes:['Le bonus local de +5 dépend uniquement des nationalités d’origine du personnage. Les passeports d’affectation ou supplémentaires ne donnent plus de bonus.','Blocs Passeports retirés des fiches et panneaux ; drapeaux de nationalité conservés. Données de passeport conservées pour compatibilité, sans effet sur les règles.','Anciennes missions : retrait du bonus de passeport lorsque le pays ne correspond pas à une nationalité d’origine. Voyage sous passeport inchangé.']},{version:'146',date:'2026-10-02',title:'Notifications et carte allégée',changes:['Enquête : les deux dossiers initiaux sont signalés dès le début de partie. Les notifications des onglets s’éteignent après consultation et redeviennent disponibles au tour suivant.','Adler possède les nationalités allemande et américaine, y compris dans les sauvegardes existantes.','Retrait des raccourcis de continents et de la barre de zoom/recentrage du globe. Les gestes de navigation restent disponibles.','Agents étrangers : affichage réactivé automatiquement à chaque nouveau tour, en solo et en multijoueur.']},{version:'145',date:'2026-10-03',title:'Reconnaissance du pays et alertes de fuite',changes:['Drone : 1 tour, 12 énergie. Ouvre l’accès local et découvre/localise tous les suspects présents, sauf l’Architecte encore inconnu. Aucun bonus d’arrestation ; intrusion numérique inchangée.','Déplacement d’une cible : pop-up avec illustration, portrait, nom et trajet du pays de départ vers le nouveau pays, uniquement pour les équipes possédant déjà son dossier.','Bureau des enquêtes : libellé de l’onglet de gauche sur deux lignes.']},{version:'144',date:'2026-10-02',title:'Globe par défaut et préférences mémorisées',changes:['Globe comme vue initiale pour les nouveaux joueurs, en solo et en multijoueur. Un choix manuel du Dôme reste disponible et mémorisé.','Mémorisation renforcée du Bureau des enquêtes entre les ouvertures, avec repli lorsque le stockage principal est indisponible.','Patch notes : dernière version affichée en premier, ouverture en haut de page et lecture mémorisée dès la consultation. L’indicateur du menu se met à jour immédiatement.','Actualisation des fichiers du jeu lors des prochaines visites pour éviter les anciennes interfaces en cache.']},{version:'143',date:'2026-10-02',title:'Mod Bureau des enquêtes',changes:['Intégration du Bureau des enquêtes : dossiers, parcours des preuves, conditions d’arrestation et affectation des agents dans une fenêtre dédiée.','Activation et désactivation dans Paramètres → Mods ; désactivé par défaut, choix mémorisé sur le navigateur. Le menu Enquête habituel reste disponible.','Adaptation aux règles actuelles : drone tactique sans preuve, intrusion sans localisation, preuves falsifiées écartées et bonus d’arrestation du drone.','Ordres transmis par le moteur habituel en solo et par l’hôte en multijoueur ; consultation seule pour les observateurs et les joueurs ayant confirmé leur tour.']},{version:'142',date:'2026-10-02',title:'Drone tactique et intrusion numérique',changes:['Drone : 2 tours, Habileté + Drones, 24 fatigue au total. Ouvre l’accès, découvre et localise une cible ; aucune preuve. +10 points à la prochaine tentative d’arrestation contre elle, non cumulables et liés à cette localisation.','Intrusion : 2 tours, Habileté + Informatique, 16 fatigue au total. Preuve disponible à vérifier, +1 tour de hack dans le pays et +1 recherche selon la règle de meilleure contribution du tour ; aucune localisation. Les preuves peuvent être falsifiées.','Hack absent : actif au tour suivant ; hack existant : durée prolongée, bonus maintenu à +10.','Descriptions, effets clés, résultats, dossiers, wiki, prestige et choix des pays IA actualisés. Anciennes mentions courantes de Soutien numérique harmonisées en Hack d’un pays.']},{version:'141',date:'2026-10-02',title:'Alerte de preuve falsifiée',changes:['Pop-up dédié après une falsification découverte : illustration, titre rouge, pays du dossier, criminel et nom de la preuve.','Alerte intégrée au débriefing de l’équipe concernée, en solo et en multijoueur.']},{version:'140',date:'2026-10-02',title:'Falsifications variables',changes:['Nouvelles parties : 3 preuves falsifiées chez 3 suspects tirés au sort, uniquement parmi leurs deux premières pièces. La troisième reste authentique.','Tirage conservé dans les sauvegardes et identique pour tous les joueurs en multijoueur.','Une falsification écartée bloque les nouvelles préparations et arrestations jusqu’au remplacement de la pièce. Les opérations déjà engagées et les préparations acquises restent conservées.','Les parties existantes gardent leurs preuves.']},{version:'139',date:'2026-10-02',title:'Prestige des vérifications',changes:['Chaque pays gagne 2 prestige lorsqu’il vérifie une preuve authentique, une seule fois par pièce et par pays.','Les scores historiques des sauvegardes restent conservés ; les nouvelles vérifications suivent la nouvelle règle.','Noms de pays retirés des étapes des dossiers d’enquête. Aides et wiki actualisés.']},{version:'138',date:'2026-10-02',title:'Confort de jeu et bilan multijoueur',changes:['Patch notes non lues mémorisées localement ; portraits de sélection adaptés aux petits écrans.','Bandeau du salon plus discret ; suspects arrêtés placés après toutes les cibles actives.','Infobulles de chronologie latérales et condensées ; chances de mission affichées dans le dossier de carte.','Flèches pour comparer les agents dans l’affectation, y compris leurs missions déjà engagées.','Bilan multijoueur transmis en fragments pour éviter la limite de taille du relais ; difficulté et agents disponibles dans le bilan final.','Cellules démantelées : seules les menaces actives sont listées dans le rapport d’annulation.','Confirmation du pays et du coût en confiance avant une démarche diplomatique.','Double-clic sur un pays pour ouvrir le déploiement.']},{version:'137',date:'2026-10-01',title:'Correction de l’entrée multijoueur',changes:['Correction de l’erreur s is not defined à l’ouverture de Rejoindre une partie.','Le choix de difficulté reste dans le salon, où son état est disponible et seul l’hôte peut le modifier.']},{version:'136',date:'2026-10-01',title:'Suspension des bonus nationaux',changes:['Bonus des pays temporairement désactivés pour les nouvelles missions de toutes les équipes, en solo et en multijoueur.','Mentions des spécialités et bonus retirées du choix des pays et de sa description, dans les deux modes.','Wiki actualisé. Les missions déjà affectées conservent leurs chances enregistrées.']},{version:'135',date:'2026-10-01',title:'Placement du bloc de nouvelle partie',changes:['Le bloc compact de configuration passe à droite et reste visible pendant le défilement.','La mention Doctrine nationale est retirée.']},{version:'134',date:'2026-10-01',title:'Nouvelle partie plus compacte',changes:['Bloc de gauche compact et fixe pendant le défilement, avec le résumé de l’équipe, la difficulté et le bouton Lancer l’opération en bas.','Suppression du texte de présentation et du bouton de reprise sur la page de nouvelle partie.','Interface remontée et choix de difficulté simplifié : Facile, Normal, Expert.']},{version:'133',date:'2026-10-01',title:'Enquêtes plus progressives en difficulté Normal',changes:['Les pays IA en Normal attendent la vérification de leur première preuve avant de lancer la recherche de la seconde.','Leur analyste réserve le soutien numérique aux missions d’arrestation et d’extraction.','Facile, Expert, protections, soins et règles de Fracture restent inchangés. Aucun bonus ou malus caché de réussite.']},{version:'132',date:'2026-10-01',title:'Ajustement léger des pays IA en Normal',changes:['En Normal, les renforts payants sont réservés aux arrestations, extractions et protections.','Expert conserve les renforts pour les préparations, vérifications et autorisations. Facile et les règles de Fracture restent inchangés.']},{version:'131',date:'2026-10-01',title:'Priorités stratégiques des pays IA experts',changes:['Le niveau Expert ne survalorise plus les voyages automatiques au détriment des enquêtes et de la protection.','La priorité stratégique reste dominante ; la durée et les chances de réussite affinent le choix. Les arrestations, préparations et protections sont privilégiées.','Aucun changement des probabilités de mission, de Fracture ou des niveaux Facile et Normal.']},{version:'130',date:'2026-10-01',title:'Niveau des pays IA',changes:['Choix Facile, Normal ou Expert à la création d’une partie solo et par l’hôte du salon multijoueur.','Les niveaux modifient uniquement les décisions des pays IA : aucune modification de Fracture, des statistiques ou des chances de réussite.','Le niveau est conservé dans les sauvegardes ; les anciennes parties restent en Normal.']},{version:'129',date:'2026-09-30',title:'Destinations de voyage',changes:['Rétablissement des catégories Superpuissances et Autres pays dans les destinations des voyages sous passeport et des passages clandestins, en conservant la présélection d’une destination disponible.']},{version:'128',date:'2026-10-01',title:'Débriefing, localisation et confort de jeu',changes:[
'Débriefing : bilans du joueur et du monde séparés, avec un bouton Skip.',
'Actions à plusieurs cibles : présélection automatique d’une cible disponible.',
'Relais satellite : actif pendant deux tours, bonus réel de +2 tours sur les positions encore valides et les nouvelles localisations.',
'Une nouvelle localisation remplace la date de validité précédente par celle de l’action qui vient de réussir.',
'Crédits disponibles affichés dans le menu d’affectation des opérations.',
'Terminologie des preuves et des arrestations harmonisée autour de « vérifier ».',
'Observateur multijoueur : espace réservé au menu pour éviter le chevauchement des commandes.',
'Historique des mises à jour accessible depuis le menu principal, à partir de cette version.'
]}];
const READ_KEY='sigma-patch-notes-read';
const seenVersion=()=>Math.max(0,Number(readPreference(READ_KEY,'0'))||0);
export function unreadPatchCount(){const seen=seenVersion();return PATCH_NOTES.filter(r=>Number(r.version)>seen).length;}
function releasePortraits(release){return release.agents?.length?`<div class="patch-agent-portraits">${release.agents.map(id=>ROSTER.find(a=>a.id===id)).filter(Boolean).map(a=>`<figure><img src="${portraitAsset(a)}" alt="Portrait de ${esc(a.name)}" width="112" height="112" loading="lazy"><figcaption><strong>${esc(a.name)}</strong><span>${esc(a.role)}</span></figcaption></figure>`).join('')}</div>`:'';}
export function patchNotesPage(){const seen=seenVersion(),releases=[...PATCH_NOTES].sort((a,b)=>Number(b.version)-Number(a.version));writePreference(READ_KEY,Math.max(seen,...releases.map(r=>Number(r.version))));return `<main class="patch-notes-page">${button('← Menu principal','main-menu','')}<span class="eyebrow">SIGMA 2040 · HISTORIQUE</span><h1>Nouveautés & patch notes</h1><p>Les mises à jour sont conservées ici à partir de la version 128.</p>${releases.map((r,i)=>`<article data-release="${esc(r.version)}" class="${Number(r.version)>seen?'patch-unread':''}"><span class="eyebrow">${Number(r.version)>seen?'NON LUE · ':''}${i===0?'DERNIÈRE MISE À JOUR · ':''}VERSION ${esc(r.version)} · ${esc(r.date)}</span><h2>${esc(r.title)}</h2>${releasePortraits(r)}<ul>${r.changes.map(c=>`<li>${esc(c)}</li>`).join('')}</ul></article>`).join('')}</main>`;}
